// Prisma client singleton. Always import `db` from here — never construct
// PrismaClient directly (hot-reload would open one connection per module
// instance and exhaust SQLite handles).
//
// R-9 (session 213): the prisma 7 migration — the client comes from the
// GENERATED tree (src/generated/prisma, regenerated by the postinstall)
// and REQUIRES a driver adapter; the v6 datasource-URL constructor option
// is gone. The adapter is PrismaLibSql (provider "sqlite", local file
// URLs) — NOT the better-sqlite3 one the upgrade guide names for SQLite:
// bun hard-blocks better-sqlite3's constructor (oven-sh/bun#4290) and this
// repo runs every process — scripts, dev server, standalone server —
// under bun. The URL itself still flows through the db-path seam
// (runtimeDatabaseUrl) — the anchoring contract is unchanged, only the
// transport moved.

import { PrismaLibSql } from "@prisma/adapter-libsql";
import { PrismaClient } from "@/generated/prisma/client";
import { runtimeDatabaseUrl } from "./db-path";

const globalForPrisma = globalThis as unknown as { __neoCrmPrisma?: PrismaClient };

function createClient(): PrismaClient {
  return new PrismaClient({
    adapter: new PrismaLibSql({ url: runtimeDatabaseUrl() }),
    log: process.env.NODE_ENV === "development" ? ["warn", "error"] : ["error"],
  });
}

export const db = globalForPrisma.__neoCrmPrisma ?? createClient();

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.__neoCrmPrisma = db;
}
